import { Link, useLocation } from 'react-router-dom';
import { Menu, X } from 'lucide-react';
import { useState } from 'react';

/**
 * Minimal editorial header — logo left, nav links right.
 * Nav links use an underline-draw hover effect.
 */
export default function Header() {
  const location = useLocation();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const navItems = [
    { href: '#about', label: 'About' },
    { href: '#contact', label: 'Contact' },
  ];

  const handleNavClick = (href: string) => {
    setIsMobileMenuOpen(false);
    if (href.startsWith('#')) {
      const el = document.querySelector(href);
      if (el) el.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <header className="fixed top-0 left-0 right-0 z-50 bg-background/90 backdrop-blur-sm">
      <div className="max-w-6xl mx-auto px-6 md:px-12">
        <div className="flex h-20 items-center justify-between">
          {/* Logo */}
          <Link to="/" className="flex items-center shrink-0">
            <img
              src="/airo-assets/images/logo/horizontal"
              alt="Alex Morgan"
              className="h-8 w-auto object-contain"
            />
          </Link>

          {/* Desktop nav */}
          <nav className="hidden md:flex items-center gap-10">
            {navItems.map((item) => (
              <button
                key={item.href}
                onClick={() => handleNavClick(item.href)}
                className="relative text-sm tracking-widest uppercase font-medium text-foreground/70 hover:text-foreground transition-colors duration-200 group"
              >
                {item.label}
                <span className="absolute -bottom-0.5 left-0 h-px w-0 bg-primary transition-all duration-300 group-hover:w-full" />
              </button>
            ))}
          </nav>

          {/* Mobile toggle */}
          <button
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            className="md:hidden p-2 text-foreground/70 hover:text-foreground transition-colors"
            aria-label="Toggle menu"
          >
            {isMobileMenuOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </div>

        {/* Mobile menu */}
        {isMobileMenuOpen && (
          <div className="md:hidden border-t border-border/40 py-6">
            <nav className="flex flex-col gap-4">
              {navItems.map((item) => (
                <button
                  key={item.href}
                  onClick={() => handleNavClick(item.href)}
                  className="text-left text-sm tracking-widest uppercase font-medium text-foreground/70 hover:text-foreground transition-colors py-1"
                >
                  {item.label}
                </button>
              ))}
            </nav>
          </div>
        )}
      </div>
    </header>
  );
}

/**
 * Minimal single-line footer — editorial and refined.
 */
export default function Footer() {
  const currentYear = new Date().getFullYear();

  return (
    <footer className="border-t border-border/40 bg-background">
      <div className="max-w-6xl mx-auto px-6 md:px-12 py-8">
        <div className="flex flex-col sm:flex-row justify-between items-center gap-3">
          <p className="text-xs tracking-widest uppercase text-muted-foreground">
            © {currentYear} Alex Morgan
          </p>
          <p className="text-xs tracking-widest uppercase text-muted-foreground">
            Built with care
          </p>
        </div>
      </div>
    </footer>
  );
}

import { Helmet } from '@dr.pogodin/react-helmet';
import { motion } from 'motion/react';
import { Github, Linkedin, Twitter, Mail, ArrowRight } from 'lucide-react';

// ─── Animation variants ───────────────────────────────────────────────────────

const fadeUp = {
  hidden: { opacity: 0, y: 28 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.55, ease: 'easeOut' as const },
  },
};

const staggerContainer = {
  hidden: {},
  visible: { transition: { staggerChildren: 0.12 } },
};

const wordFade = {
  hidden: { opacity: 0, y: 20 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.4, ease: 'easeOut' as const },
  },
};

// ─── Decorative dot-grid background ──────────────────────────────────────────

function DotGrid() {
  return (
    <div
      className="absolute inset-0 pointer-events-none"
      style={{
        backgroundImage:
          'radial-gradient(circle, hsl(var(--border)) 1px, transparent 1px)',
        backgroundSize: '28px 28px',
        opacity: 0.45,
      }}
    />
  );
}

// ─── Geometric accent shapes ──────────────────────────────────────────────────

function AccentSquare({ className = '' }: { className?: string }) {
  return (
    <span
      className={`inline-block w-2 h-2 border border-primary ${className}`}
      aria-hidden="true"
    />
  );
}

function AccentLine({ className = '' }: { className?: string }) {
  return (
    <span
      className={`inline-block h-px bg-primary ${className}`}
      aria-hidden="true"
    />
  );
}

// ─── Hero Section ─────────────────────────────────────────────────────────────

function HeroSection() {
  const nameWords = ['Alex', 'Morgan'];

  return (
    <section className="relative min-h-screen flex items-center overflow-hidden bg-background pt-20">
      <DotGrid />

      {/* Decorative right-side geometric cluster */}
      <div className="absolute right-8 md:right-16 top-1/2 -translate-y-1/2 hidden md:flex flex-col items-center gap-5 opacity-60">
        <AccentLine className="w-px h-24" />
        <AccentSquare />
        <AccentLine className="w-px h-16" />
        <div className="w-1.5 h-1.5 rounded-full bg-primary" />
        <AccentLine className="w-px h-32" />
        <AccentSquare />
        <AccentLine className="w-px h-12" />
      </div>

      <div className="relative max-w-6xl mx-auto px-6 md:px-12 w-full">
        <div className="max-w-4xl">
          {/* Eyebrow */}
          <motion.div
            initial={{ opacity: 0, x: -16 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.4, ease: 'easeOut' }}
            className="flex items-center gap-3 mb-10"
          >
            <AccentLine className="w-8" />
            <span className="text-xs tracking-widest uppercase text-primary font-medium">
              Portfolio
            </span>
          </motion.div>

          {/* Name — staggered word entrance */}
          <motion.h1
            variants={staggerContainer}
            initial="hidden"
            animate="visible"
            className="font-heading text-7xl sm:text-8xl md:text-[9rem] lg:text-[11rem] leading-none tracking-tight text-foreground mb-8"
          >
            {nameWords.map((word) => (
              <motion.span
                key={word}
                variants={wordFade}
                className="block"
              >
                {word}
              </motion.span>
            ))}
          </motion.h1>

          {/* Tagline */}
          <motion.p
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.55, ease: 'easeOut' }}
            className="text-lg md:text-xl text-foreground/60 font-light max-w-md leading-relaxed"
          >
            Designer &amp; developer crafting thoughtful digital experiences
            that balance form with function.
          </motion.p>

          {/* CTA */}
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.4, delay: 0.8 }}
            className="mt-12"
          >
            <button
              onClick={() => {
                document.querySelector('#contact')?.scrollIntoView({ behavior: 'smooth' });
              }}
              className="group inline-flex items-center gap-3 text-sm tracking-widest uppercase font-medium text-foreground hover:text-primary transition-colors duration-200"
            >
              Get in touch
              <ArrowRight
                size={14}
                className="transition-transform duration-200 group-hover:translate-x-1"
              />
            </button>
          </motion.div>
        </div>
      </div>
    </section>
  );
}

// ─── About Section ────────────────────────────────────────────────────────────

const skills = [
  'Design Systems',
  'Frontend Dev',
  'UX Strategy',
  'Typography',
  'Motion',
  'Branding',
];

function AboutSection() {
  return (
    <section id="about" className="py-32 bg-background">
      <div className="max-w-6xl mx-auto px-6 md:px-12">
        <motion.div
          variants={staggerContainer}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: '-80px' }}
          className="grid md:grid-cols-2 gap-16 md:gap-24 items-start"
        >
          {/* Left — headline */}
          <motion.div variants={fadeUp}>
            <div className="flex items-center gap-3 mb-6">
              <AccentSquare />
              <span className="text-xs tracking-widest uppercase text-primary font-medium">
                About
              </span>
            </div>
            <h2 className="font-heading text-5xl md:text-6xl leading-tight text-foreground">
              Craft over
              <br />
              <em className="not-italic text-primary">convention.</em>
            </h2>
            <AccentLine className="w-12 mt-8" />
          </motion.div>

          {/* Right — bio + skills */}
          <motion.div variants={fadeUp} className="space-y-8">
            <p className="text-base md:text-lg text-foreground/70 leading-relaxed">
              I'm a multidisciplinary designer and developer with a passion for
              building products that feel as good as they look. With over a
              decade of experience across agencies, startups, and in-house
              teams, I bring a systems-thinking approach to every project.
            </p>
            <p className="text-base md:text-lg text-foreground/70 leading-relaxed">
              My work lives at the intersection of visual design and engineering
              — where pixel-perfect interfaces meet clean, maintainable code.
              I believe the best digital experiences are invisible: they just
              work, beautifully.
            </p>

            {/* Skill chips */}
            <div className="flex flex-wrap gap-2 pt-2">
              {skills.map((skill) => (
                <span
                  key={skill}
                  className="px-3 py-1.5 text-xs tracking-wider uppercase border border-foreground/20 text-foreground/60 hover:border-primary hover:text-primary transition-colors duration-200 cursor-default"
                >
                  {skill}
                </span>
              ))}
            </div>
          </motion.div>
        </motion.div>
      </div>
    </section>
  );
}

// ─── Contact Section ──────────────────────────────────────────────────────────

const socials = [
  {
    label: 'GitHub',
    href: 'https://github.com',
    icon: Github,
  },
  {
    label: 'LinkedIn',
    href: 'https://linkedin.com',
    icon: Linkedin,
  },
  {
    label: 'Twitter / X',
    href: 'https://twitter.com',
    icon: Twitter,
  },
];

function ContactSection() {
  return (
    <section id="contact" className="py-32 bg-muted/30">
      <div className="max-w-6xl mx-auto px-6 md:px-12">
        <motion.div
          variants={staggerContainer}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: '-80px' }}
          className="grid md:grid-cols-2 gap-16 md:gap-24 items-end"
        >
          {/* Left — heading */}
          <motion.div variants={fadeUp}>
            <div className="flex items-center gap-3 mb-6">
              <AccentSquare />
              <span className="text-xs tracking-widest uppercase text-primary font-medium">
                Contact
              </span>
            </div>
            <h2 className="font-heading text-5xl md:text-6xl lg:text-7xl leading-tight text-foreground">
              Let's
              <br />
              <em className="not-italic text-primary">talk.</em>
            </h2>
            <p className="mt-6 text-base text-foreground/60 leading-relaxed max-w-xs">
              Have a project in mind or just want to say hello? My inbox is
              always open.
            </p>
          </motion.div>

          {/* Right — email + socials */}
          <motion.div variants={fadeUp} className="space-y-10">
            {/* Email link */}
            <div>
              <p className="text-xs tracking-widest uppercase text-foreground/40 mb-3">
                Email
              </p>
              <a
                href="mailto:hello@alexmorgan.co"
                className="group inline-flex items-center gap-3 text-xl md:text-2xl font-medium text-foreground hover:text-primary transition-colors duration-200"
              >
                <Mail size={20} className="text-primary shrink-0" />
                hello@alexmorgan.co
                <ArrowRight
                  size={16}
                  className="opacity-0 -translate-x-2 group-hover:opacity-100 group-hover:translate-x-0 transition-all duration-200"
                />
              </a>
            </div>

            {/* Divider */}
            <AccentLine className="w-full opacity-30" />

            {/* Social icons */}
            <div>
              <p className="text-xs tracking-widest uppercase text-foreground/40 mb-5">
                Find me on
              </p>
              <div className="flex items-center gap-4">
                {socials.map(({ label, href, icon: Icon }) => (
                  <a
                    key={label}
                    href={href}
                    target="_blank"
                    rel="noopener noreferrer"
                    aria-label={label}
                    className="group flex items-center justify-center w-11 h-11 border border-foreground/20 text-foreground/50 hover:border-primary hover:text-primary hover:scale-105 transition-all duration-200"
                  >
                    <Icon size={18} />
                  </a>
                ))}
              </div>
            </div>
          </motion.div>
        </motion.div>
      </div>
    </section>
  );
}

// ─── Page ─────────────────────────────────────────────────────────────────────

export default function HomePage() {
  return (
    <>
      <Helmet>
        <title>Alex Morgan — Designer &amp; Developer</title>
        <meta
          name="description"
          content="Personal portfolio of Alex Morgan — a multidisciplinary designer and developer crafting thoughtful digital experiences."
        />
      </Helmet>

      <main>
        <HeroSection />
        <AboutSection />
        <ContactSection />
      </main>
    </>
  );
}

